	router.POST(options.BaseURL+"/api/v1/machines", wrapper.CreateMachine)
	router.DELETE(options.BaseURL+"/api/v1/machines/:id", wrapper.DeleteMachine)
	router.GET(options.BaseURL+"/api/v1/machines/:id", wrapper.GetMachine)
